local changed=0
local function waterKey(r)return table.concat({r.game,r.style,r.tileset,r.map or '',r.id,r.quadrant,r.x or '',r.y or ''},':')end
for index,prior in ipairs(rows)do local u=waterUpdates[waterKey(prior)]
 if u then local row={}for k,v in pairs(prior)do row[k]=v end
  row[u.field]=waterTemplates[row.game].donor;row.animation=waterTemplates[row.game].animation;row.animated=true
  row.role=u.role;row.compositionPixelHash=u.hash
  row.coastalWaterFamilyReview={reason=u.reason,native_ocean_mid=368,original_pixel_scale=1,whole_native_overlay_unchanged=true,complete_eight_frame_sequence=true}
  row.evidence="Reviewed coherent native coastal water family. Complete native Emerald368 ocean and all8 original general_water frames match the existing Emerald393/402/410 banks. Only the native water donor/underlay and matching animation metadata change. Original complete rock/shore/whirlpool layers, all8 whirlpool asset-frame entries and order, source hashes/collisions/palettes/priority, field-state destinations, item/NPC positions, maps, Surf/fishing, scripts and native game mechanics remain unchanged. Route32 joins its actual Emerald393/402 marine banks; coherent Kanto FireRed coasts and inland/cave water are excluded."
  rows[index]=row;changed=changed+1
 end
end
assert(changed==156,'Coastal native water source set changed')
-- END COHERENT NATIVE JOHTO COASTAL WATER FAMILY
return rows
